// src/routes/undoSnapshot.ts
init_errors();
function undoSnapshot(mountPrefix) {
  const MUTATING = ["POST", "PATCH", "PUT", "DELETE"];
  const MANAGED = ["/play", "/undo", "/redo"];
  const TOKEN_PATH = /^\/providers\/[^/]+\/token$/;
  return async (c, next) => {
    const full = c.req.path;
    const mounted = full.startsWith(mountPrefix) ? full.slice(mountPrefix.length) || "/" : full;
    const isMutating = MUTATING.includes(c.req.method);
    const isManaged = MANAGED.some((p) => mounted === p || mounted.startsWith(`${p}/`)) || TOKEN_PATH.test(mounted);
    if (isMutating && !isManaged) {
      try {
        await snapshot();
      } catch (e) {
        console.log(`[history] snapshot failed: ${errMessage(e)}`);
      }
    }
    await next();
  };
}

// src/buildServer.ts
var API_PREFIX = "/api";
function buildServer({ publicDir }) {
  const root = new Hono2();
  root.onError((err, c) => {
    console.log(`[queuepilot-web] unhandled error on ${c.req.method} ${c.req.path}: ${errMessage(err)}`);
    return c.json({ error: errMessage(err) }, 500);
  });
  const api = new Hono2();
  api.use("*", undoSnapshot(API_PREFIX));
  api.route("/", historyRoutes());
  api.route("/", queuesRoutes());
  api.route("/", setsRoutes());
  api.route("/", plexMetadataRoutes());
  api.route("/", providersRoutes());
  api.route("/", playbackRoutes());
  api.route("/", sseRoutes());
  root.route(API_PREFIX, api);
  root.route("/", launcherRoutes());
  root.use("*", createStaticHandler({ rootDir: publicDir, hasSpaFallback: false }));
  return root;
}

